  const minutos = Math.round((fecha - Date.now()) / 60000);
  if (minutos < 0) return `Vencido ${tiempoRelativo(iso)}`;
  if (minutos < 1) return 'Ahora mismo';
  if (minutos < 60) return `En ${minutos} min`;
  const horas = Math.round(minutos / 60);
