  document.getElementById('drawer').classList.add('open');
  document.getElementById('drawerBg').classList.add('open');
  navPush({ type: 'drawer' });
  document.getElementById('perfil-avatar-btn').onclick = () => document.getElementById('perfil-avatar-file').click();
